using DualOntologyWorldEngine.Core;
using System.Collections.Immutable;
static class ScopeRegressionProgram {
static int checks;
static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
static void Main(){
var w=new WorldRuntime();var s=new SoulEssence("owner");var other=new SoulEssence("other");var b=new Essence("body",ProjectionKind.Body);var st=b.Add(new StateProperty());var scoped=new Tag("scoped");var permanent=new Tag("permanent");var done=new Tag("done");var gate=new Tag("gate");st.Values[scoped]=3;st.Observable.UnionWith([scoped,permanent,done,gate]);w.Project(s,"owner");w.Project(other,"other");var rb=w.Project(b,"body");s.Relations.Add((Relations.Controls,b));var p=w.Observe(s,[rb])[0];var op=w.Observe(other,[rb])[0];var session=new SimulationSession(w);var c=new Condition.Tagged(p,gate,1);
void Observe(SoulEssence soul,Projection target,int? value){Observation.Observe(soul,new(target.Name,target.Kind){Target=target,Tags=ImmutableDictionary<Tag,int?>.Empty.Add(gate,value)});}
Effect Flow(Effect tail)=>new Effect.Sequence([new Effect.Set(p,permanent,7),new Effect.TemporarySetUntilEnd(p,scoped,9),new Effect.Wait(c,tail)]);
ActionExecution Start(Effect tail){Observe(s,p,0);var e=session.Submit(s,new(p,Flow(tail),0));session.CTB.RunUntil(session.CTB.Now);return e;}
void Free(){var x=session.Submit(s,new(p,new Effect.Set(p,done,0),0));session.CTB.RunUntil(session.CTB.Now);Check(x.Status==ExecutionStatus.Completed,"body slot reusable");}
var e=Start(new Effect.Change(p,done,1));session.CTB.RunUntil(1e12);Check(e.Status==ExecutionStatus.Pending&&e.WaitingFor!=null&&b.Get<TemporaryStateProperty>()!.Override(scoped)==9,"large CTB preserves scoped state and waiting");bool blocked=false;try{session.Submit(s,new(p,new Effect.Set(p,done,5),0));}catch(InvalidOperationException){blocked=true;}Check(blocked,"waiting occupies body");Observe(other,op,1);Check(e.Scheduled==null,"wrong soul cannot wake");Observe(s,p,null);Observe(s,p,0);Check(e.Scheduled==null,"false and withdrawn conditions remain waiting");Observe(s,p,1);Observe(s,p,1);Check(session.CTB.Pending.Count()==1,"repeated true notifications schedule once");session.CTB.RunUntil(session.CTB.Now);Check(e.Status==ExecutionStatus.Completed&&st.Values[done]==1,"correct owner observation resumes once");Check(b.Get<TemporaryStateProperty>()!.Active.Count==0&&rb.Tags[scoped]==3,"normal completion restores underlying state");Check(!session.Cancel(e),"completed scope cancellation idempotent");Free();
e=Start(new Effect.Sequence([new Effect.Require(new Condition.Constant(Truth.False)),new Effect.Set(p,done,88)]));Observe(s,p,1);session.CTB.RunUntil(session.CTB.Now);Check(e.Status==ExecutionStatus.Failed&&e.Result!.Failure==ActionFailure.ConditionFailed,"continuation Require fails");Check(b.Get<TemporaryStateProperty>()!.Active.Count==0&&st.Values[permanent]==7&&st.Values[done]==0,"failure cleans lease preserves earlier commit rejects failed stage");Check(!session.Cancel(e),"failed scope cancellation idempotent");Free();
e=Start(new Effect.Set(p,done,6));Check(session.Cancel(e)&&!session.Cancel(e)&&b.Get<TemporaryStateProperty>()!.Active.Count==0,"cancel clears once");Observe(s,p,1);session.CTB.RunUntil(session.CTB.Now);Check(e.Status==ExecutionStatus.Cancelled&&st.Values[done]==0,"cancel detaches observation continuation");Free();
var timed=session.Submit(s,new(p,new Effect.Sequence([new Effect.TemporarySet(p,scoped,11,100),new Effect.Wait(1,new Effect.Require(new Condition.Constant(Truth.False)))]),0));session.CTB.RunUntil(session.CTB.Now+1);Check(timed.Status==ExecutionStatus.Failed&&b.Get<TemporaryStateProperty>()!.Active.Count==0&&!session.CTB.Pending.Any(),"failure also immediately clears legacy timed lease and expiry");var old=session.Submit(s,new(p,new Effect.Wait(5,new Effect.Set(p,done,2)),0));session.CTB.RunUntil(session.CTB.Now);var now=session.CTB.Now;session.CTB.RunUntil(now+4);Check(old.Status==ExecutionStatus.Pending,"old delay remains pending before due");session.CTB.RunUntil(now+5);Check(old.Status==ExecutionStatus.Completed&&st.Values[done]==2,"old delay completes at due");
e=Start(new Effect.Set(p,done,99));session.Dispose();session.Dispose();Check(e.Status==ExecutionStatus.Cancelled&&b.Get<TemporaryStateProperty>()!.Active.Count==0&&!session.Cancel(e),"Dispose clears scope idempotently");Observe(s,p,1);session.CTB.RunUntil(session.CTB.Now);Check(st.Values[done]==2&&!session.CTB.Pending.Any(),"Dispose removes observer and scheduled work");
// Permit only lifts a prohibition of equal or lower weight; it never proposes an action or adds score.
IReadOnlyList<DecisionAssessment> Decide(params (RuleMode Mode,int Weight)[] specs){var dw=new WorldRuntime();var ds=new SoulEssence("decider");var db=new Essence("dbody",ProjectionKind.Body);db.Add(new StateProperty()).Observable.Add(done);dw.Project(ds,"decider");var drb=dw.Project(db,"dbody");ds.Relations.Add((Relations.Controls,db));var me=dw.Observe(ds,[drb])[0];var act=new Effect.Set(me,done,1);Observation.Observe(ds,new("habit",ProjectionKind.Concept){Source=ObservationSource.Introspection,Existence=Truth.True,Rules=[..specs.Select(x=>new Rule(new Condition.Constant(Truth.True),x.Mode,act,x.Weight,Truth.True))]});return DecisionSystem.Assess(ds.World,me);}
Check(Decide((RuleMode.Permit,5)).Count==0,"permit alone proposes nothing");
var lifted=Decide((RuleMode.Prefer,3),(RuleMode.Forbid,2),(RuleMode.Permit,2));Check(lifted.Count==1&&!lifted[0].Forbidden&&lifted[0].Decision.Score==3,"permit of equal weight lifts a prohibition without adding score");
var kept=Decide((RuleMode.Prefer,3),(RuleMode.Forbid,3),(RuleMode.Permit,2));Check(kept.Count==1&&kept[0].Forbidden,"weaker permit leaves the prohibition");
var local=new Rule(new Condition.Constant(Truth.True),RuleMode.Prefer,new Effect.Set(p,done,1),3,Truth.True,LifetimeScope.Chapter,"scope-test");
Observation.Observe(s,new(p.Name,p.Kind){Target=p,Rules=[local]});
Observe(s,p,1);
Check(p.Rules.Single().Lifetime==LifetimeScope.Chapter&&p.Rules.Single().LifetimeOwner=="scope-test","ordinary observations preserve rule lifetime");
var snapshot=s.World.CaptureSnapshot();
Check(snapshot is ContractResult<CognitionSnapshotV1>.Success frozen&&frozen.Value.Projections.Single(x=>x.Id==p.SubjectId).Rules.Single().LifetimeOwner=="scope-test","frozen cognition preserves lifetime owner");
var revision=s.World.Revision;bool invalidScope=false;
try{Observation.Observe(s,new(p.Name,p.Kind){Target=p,Rules=[local with{LifetimeOwner=null}]});}catch(InvalidOperationException){invalidScope=true;}
Check(invalidScope&&s.World.Revision==revision&&p.Rules.Single().LifetimeOwner=="scope-test","ownerless local rule is rejected atomically");
Console.WriteLine($"TOTAL {checks} checks");
}}
